/** Functional programming utilities: curry, compose, pipe. */
type AnyFunction = (...args: any[]) => any;
/** Curries a function, allowing partial application of arguments. */
export declare const curry: <F extends AnyFunction>(fn: F) => (...args: any[]) => any;
/** Right-to-left function composition. */
export declare const compose: (...fns: ((arg: any) => any)[]) => (arg: any) => any;
/** Left-to-right function piping. */
export declare const pipe: (...fns: ((arg: any) => any)[]) => (arg: any) => any;
export {};
